namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
    public bool IsFeatured { get; set; }
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public int InstructorId { get; set; }
    public Instructor Instructor { get; set; } = null!;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 research papers and holds two patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez focuses on applied mathematics and statistical modeling. He received the University Teaching Excellence Award in 2024.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Prof. Sarah Williams", Title = "Professor of English", Bio = "Prof. Williams is an expert in American literature and creative writing. She is the author of three critically acclaimed novels.", Email = "swilliams@university.edu" },
            new() { Id = 4, Name = "Dr. James Park", Title = "Professor of Physics", Bio = "Dr. Park researches quantum mechanics and particle physics. He previously worked at CERN and has contributed to several landmark discoveries.", Email = "jpark@university.edu" },
            new() { Id = 5, Name = "Dr. Maria Johnson", Title = "Associate Professor of History", Bio = "Dr. Johnson specializes in modern European history. Her latest book on post-war reconstruction was a finalist for the National Book Award.", Email = "mjohnson@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Assistant Professor of Computer Science", Bio = "Dr. Kim focuses on cybersecurity and distributed systems. Before joining academia he spent ten years in industry at leading tech companies.", Email = "dkim@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and basic algorithms. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", MaxEnrollment = 120, CurrentEnrollment = 98, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Prerequisite: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Science Hall 305", MaxEnrollment = 80, CurrentEnrollment = 72, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 310", Title = "Computer Networks", Description = "Explore the principles of computer networking including protocols, network architecture, routing, and security. Hands-on labs with real network configurations.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", MaxEnrollment = 60, CurrentEnrollment = 45, IsFeatured = false, DepartmentId = 1, InstructorId = 6 },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential and integral calculus. Topics include limits, derivatives, integrals, and the fundamental theorem of calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 100", MaxEnrollment = 150, CurrentEnrollment = 130, IsFeatured = true, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205", MaxEnrollment = 80, CurrentEnrollment = 55, IsFeatured = false, DepartmentId = 2, InstructorId = 2 },
            new() { Id = 6, Code = "ENG 101", Title = "College Writing", Description = "Develop essential writing skills through practice in expository and argumentative essays. Emphasis on clarity, structure, and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 102", MaxEnrollment = 30, CurrentEnrollment = 28, IsFeatured = false, DepartmentId = 3, InstructorId = 3 },
            new() { Id = 7, Code = "ENG 220", Title = "American Literature", Description = "Survey of major works in American literature from the colonial period to the present. Readings include novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities Hall 210", MaxEnrollment = 40, CurrentEnrollment = 32, IsFeatured = true, DepartmentId = 3, InstructorId = 3 },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Introductory physics covering mechanics, thermodynamics, and waves. Includes weekly lab sessions. Corequisite: MATH 101.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Science Hall 150", MaxEnrollment = 100, CurrentEnrollment = 85, IsFeatured = false, DepartmentId = 4, InstructorId = 4 },
            new() { Id = 9, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, and measurement. Prerequisite: PHYS 201, MATH 201.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Science Hall 320", MaxEnrollment = 40, CurrentEnrollment = 22, IsFeatured = false, DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations and events from prehistory through the late medieval period, including the rise and fall of empires.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Liberal Arts 300", MaxEnrollment = 90, CurrentEnrollment = 65, IsFeatured = false, DepartmentId = 5, InstructorId = 5 },
            new() { Id = 11, Code = "HIST 250", Title = "Modern European History", Description = "Examine the political, social, and cultural transformations in Europe from the French Revolution to the present day.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Location = "Liberal Arts 315", MaxEnrollment = 50, CurrentEnrollment = 38, IsFeatured = true, DepartmentId = 5, InstructorId = 5 },
            new() { Id = 12, Code = "CS 420", Title = "Machine Learning", Description = "Study the theory and practice of machine learning including supervised and unsupervised learning, neural networks, and model evaluation. Prerequisite: CS 201, MATH 201.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Tech Building 205", MaxEnrollment = 50, CurrentEnrollment = 48, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
        ];

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? minCredits, int? maxCredits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (minCredits.HasValue)
            query = query.Where(c => c.Credits >= minCredits.Value);

        if (maxCredits.HasValue)
            query = query.Where(c => c.Credits <= maxCredits.Value);

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course is null || course.CurrentEnrollment >= course.MaxEnrollment)
            return false;

        // In a real app this would persist to a database
        course.CurrentEnrollment++;
        return true;
    }
}

