arguments.file_text:
@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-4">
        <label for="search" class="form-label">Search</label>
        <input id="search" type="text" class="form-control" placeholder="Search by title, code, or keyword…"
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <label for="department" class="form-label">Department</label>
        <select id="department" class="form-select" @bind="SelectedDepartmentId">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <label for="minCredits" class="form-label">Min Credits</label>
        <select id="minCredits" class="form-select" @bind="MinCredits">
            <option value="">Any</option>
            <option value="3">3</option>
            <option value="4">4</option>
        </select>
    </div>
    <div class="col-md-2">
        <label for="maxCredits" class="form-label">Max Credits</label>
        <select id="maxCredits" class="form-select" @bind="MaxCredits">
            <option value="">Any</option>
            <option value="3">3</option>
            <option value="4">4</option>
        </select>
    </div>
</div>

@{
    var results = Catalog.SearchCourses(SearchTerm, SelectedDepartmentId, MinCredits, MaxCredits);
}

<p class="text-muted">Showing @results.Count course(s)</p>

<table class="table table-striped table-hover">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th>Availability</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in results)
        {
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@course.Department.Name</td>
                <td>@course.Credits</td>
                <td>@course.Schedule</td>
                <td>
                    @{
                        var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
                        var badgeClass = spotsLeft <= 5 ? "bg-danger" : spotsLeft <= 20 ? "bg-warning text-dark" : "bg-success";
                    }
                    <span class="badge @badgeClass">@spotsLeft spots left</span>
                </td>
                <td>
                    <a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                </td>
            </tr>
        }
    </tbody>
</table>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try broadening your filters.</div>
}

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private string? SearchTerm { get; set; }
    private int? SelectedDepartmentId { get; set; }
    private int? MinCredits { get; set; }
    private int? MaxCredits { get; set; }

    protected override void OnInitialized()
    {
        if (DepartmentId.HasValue)
            SelectedDepartmentId = DepartmentId;
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your request to enroll in
            <strong>@(Catalog.GetCourse(Model.CourseId)?.Title ?? "the selected course")</strong>
            has been received. You will receive a confirmation at your university email.</p>
        <a href="/" class="btn btn-primary">Return Home</a>
        <a href="courses" class="btn btn-outline-secondary">Browse More Courses</a>
    </div>
}
else
{
    @if (Failed)
    {
        <div class="alert alert-danger">
            The enrollment request could not be processed. The course may be full or invalid. Please try again.
        </div>
    }

    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input id="studentName" type="text" class="form-control" required
                           @bind="Model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input id="studentId" type="text" class="form-control" required
                           placeholder="e.g. S12345678"
                           @bind="Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <select id="courseSelect" class="form-select" required @bind="Model.CourseId">
                        <option value="0" disabled>— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool Submitted { get; set; }
    private bool Failed { get; set; }

    protected override void OnInitialized()
